// 640x480 at 60 Hz timing from a 25 MHz pixel clock.
// Monitors accept 25.000 MHz in place of 25.175 MHz (0.7% slow, 59.5 Hz).
module vga_timing (
  input  wire       clk25,
  output reg  [9:0] h = 0,         // 0..799, pixel within the line
  output reg  [9:0] v = 0,         // 0..524, line within the frame
  output wire       hsync_n,       // active low
  output wire       vsync_n,       // active low
  output wire       visible
);
  always @(posedge clk25) begin
    if (h == 799) begin
      h <= 0;
      v <= (v == 524) ? 0 : v + 1;
    end else begin
      h <= h + 1;
    end
  end

  // 640 visible + 16 front porch = 656: the sync pulse lasts 96 clocks.
  assign hsync_n = ~(h >= 656 && h < 752);
  // 480 visible + 10 front porch = 490: the sync pulse lasts 2 lines.
  assign vsync_n = ~(v >= 490 && v < 492);
  assign visible = (h < 640) && (v < 480);
endmodule

// In the top level, force the colour outputs to zero outside the
// visible area, or the monitor will mistake them for the black level:
